function codeValide(texte) {
  if (texte.length !== 8 || texte[3] !== "-") {
    return false;
  }
  for (let i = 0; i < 8; i++) {
    const c = texte[i];
    if (i < 3 && !(c >= "A" && c <= "Z")) {
      return false;
    }
    if (i > 3 && !(c >= "0" && c <= "9")) {
      return false;
    }
  }
  return true;
}

