function extraireCodes(texte) {
  const codes = [];
  let i = 0;
  while (i + 8 <= texte.length) {
    const morceau = texte.slice(i, i + 8);
    let ok = morceau[3] === "-";
    for (let k = 0; k < 8 && ok; k++) {
      const c = morceau[k];
      if (k < 3 && !(c >= "A" && c <= "Z")) ok = false;
      if (k > 3 && !(c >= "0" && c <= "9")) ok = false;
    }
    if (ok) {
      codes.push(morceau);
      i += 8;
    } else {
      i += 1;
    }
  }
  return codes;
}

