solution.javascript:
function correspond(motif, texte) {
  const n = texte.length;
  // prec[j] : les premiers caractères du motif traités correspondent à texte[0..j[
  let prec = new Array(n + 1).fill(false);
  prec[0] = true;
  for (const m of motif) {
    const cur = new Array(n + 1).fill(false);
    if (m === "*") {
      cur[0] = prec[0];
      for (let j = 1; j <= n; j++) {
        cur[j] = prec[j] || cur[j - 1];
      }
    } else {
      for (let j = 1; j <= n; j++) {
        cur[j] = prec[j - 1] && (m === "?" || m === texte[j - 1]);
      }
    }
    prec = cur;
  }
  return prec[n];
}

